import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { api } from '../api';

const AuthPage = () => {
  const [isLogin, setIsLogin] = useState(true);
  const [formData, setFormData] = useState({ username: '', password: '' });
  const [error, setError] = useState('');
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    try {
      if (isLogin) {
        // Практика 8-9: Получаем токены и сохраняем их
        const data = await api.login(formData);
        localStorage.setItem('accessToken', data.accessToken);
        localStorage.setItem('refreshToken', data.refreshToken);
        navigate('/'); // Идем в магазин
      } else {
        await api.register(formData);
        setIsLogin(true);
        alert('Успешно! Теперь войдите.');
      }
    } catch (err) {
      setError(err.response?.data?.error || 'Произошла ошибка');
    }
  };

  return (
    <div style={{ display: 'flex', justifyContent: 'center', marginTop: '100px' }}>
      <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '15px', width: '300px' }}>
        <h2>{isLogin ? 'Вход' : 'Регистрация'}</h2>
        {error && <p style={{ color: 'red' }}>{error}</p>}
        
        <input 
          placeholder="Логин (username)" 
          value={formData.username} 
          onChange={e => setFormData({...formData, username: e.target.value})} 
          required 
          style={{ padding: '10px' }}
        />
        <input 
          type="password" 
          placeholder="Пароль" 
          value={formData.password} 
          onChange={e => setFormData({...formData, password: e.target.value})} 
          required 
          style={{ padding: '10px' }}
        />
        
        <button type="submit" style={{ padding: '10px', background: '#d4418e', color: 'white', border: 'none' }}>
          {isLogin ? 'Войти' : 'Зарегистрироваться'}
        </button>
        
        <button type="button" onClick={() => setIsLogin(!isLogin)} style={{ background: 'none', border: 'none', color: '#6366f1', cursor: 'pointer' }}>
          {isLogin ? 'Нет аккаунта? Зарегистрироваться' : 'Уже есть аккаунт? Войти'}
        </button>
      </form>
    </div>
  );
};

export default AuthPage;
